"""Build an offline, self-contained companion chapter. pip install markdown2 latex2mathml"""
from pathlib import Path
import sys,re,html
for p in ['/tmp/cmp-site','/tmp/qm-math']:
 if Path(p).exists():sys.path.insert(0,p)
import markdown2
from latex2mathml.converter import convert
R=Path(__file__).resolve().parents[1]
def slider(id,label,min,max,step,value,unit=''):
 return f'<label for="{id}">{label} <output id="{id}-out">{value}{unit}</output><input id="{id}" type="range" min="{min}" max="{max}" step="{step}" value="{value}"></label>'
def select(id,label,options):
 return f'<label for="{id}">{label}<select id="{id}">'+''.join(f'<option value="{v}">{t}</option>' for v,t in options)+'</select></label>'
def demo(id,num,title,prompt,controls,result,source,extra='',animated=True,wide=False,note=''):
 return f'''<section class="demo {'wide-canvas' if wide else ''}" id="{id}" aria-labelledby="{id}-title"><div class="demo-head"><div><div class="demo-no">INTERACTIVE {num} / 教学扩展</div><h4 id="{id}-title">{title}</h4></div>{'<button data-play aria-pressed="true">暂停动画</button>' if animated else ''}</div><div class="prompt">先预测 → {prompt}</div><div class="demo-body"><canvas aria-label="{title}，由下方控件操作" role="img"></canvas>{extra}<div class="controls">{controls}</div><div class="result" id="{result}" role="status" aria-live="off">模型载入后显示结果。</div><p class="note">{note}</p><details><summary>查看这个演示的实际 JavaScript 源码</summary><pre><code data-source="{source}"></code></pre><div class="source-links"><a href="assets/physics.js" download>下载数值核心 JS</a><a href="examples.py" download>下载 NumPy 算例</a></div></details></div></section>'''
demos={}
demos['## 02']=demo('symmetry-demo','01','“图形没变”，原子也没动吗？','C₂ 旋转后，①号原子会落在哪里？','<button id="apply-c2">施加 C₂(z) · 180°</button><button id="geometry-reset">恢复初态</button>'+select('geometry-isotope','系统',[('h2o','H₂O · 两个同种 H'),('hdo','HDO · 一侧换为 D')])+'<label><span>追踪编号</span><span><input type="checkbox" id="show-atom-labels" checked> 显示 ①②</span></label>','symmetry-status','symmetry',note='示意采用理想平衡结构；虚线圈是参考位置。连续转动帮助追踪原子，只有终点用来判断所选对称操作。')
demos['## 03']=demo('dimer-demo','02','对称性不变，能差仍然可以变','保持 δ=0，改变 t；再只改变 δ。',slider('dimer-t','轨道耦合 t',-2,2,.05,-1)+slider('dimer-delta','左右不等价 δ',0,1.5,.05,0)+'<button id="dimer-reset">重置</button>','dimer-status','dimer',animated=False,note='只画两条正交局域轨道的系数；蓝与红表示正负相位。左右振幅整体同时变号，不改变物理态。ε=0。')
demos['## 04']=demo('selection-demo','03','让“禁止”成为看得见的面积相消','纯奇末态时，x 与 x² 哪个给出零积分？',select('operator','算符 O',[('x2','x² · 偶算符'),('x','x · 奇算符')])+select('final-state','末态',[('mixed','cosα φ₁ + sinα φ₂'),('phi3','φ₃ · 允许但仍为零的例子')])+slider('mix-angle','混合角 α',0,45,1,0)+'<button id="selection-reset">重置</button>','selection-status','selection',note='数值积分区间 [−7,7]，1400 等分 Simpson；解析结果对应全实轴。选 φ₃ 时请使用 x 算符，观察额外振子选择定则。')
demos['### 4.2']=demo('ring-demo','04','一次换基，把四轨道问题拆成块','四条边相同与只改一条边，变换后的矩阵有何区别？',slider('ring-t','统一耦合 t',-2,-.2,.05,-1)+slider('ring-eta','单边改变量 η',0,1.5,.05,0)+select('ring-vector','观察对称基',[('0','s · 全同号'),('1','a · 交替正负'),('2','u · 对置组合'),('3','v · 另一对置组合')])+'<button id="ring-reset">重置</button>','ring-status','ring',extra='<div class="matrix-layout" id="ring-matrices"></div>',note='ε=0。矩阵中浅金色格为非零项；环上金色点的运动只是系数示意，不是电子运动轨迹。')
demos['### 4.3']=demo('ligand-demo','05','中心轨道与配体组合：谁能和谁混合？','中心 s 与配体反对称组合能够耦合吗？',select('central-orbital','中心轨道',[('s','s · 偶'),('p','p_z · 奇')])+select('ligand-channel','配体组合',[('+','L + R · 偶'),('-','L − R · 奇')])+slider('ligand-v','候选耦合 v',0,1.2,.05,.5)+'<button id="ligand-reset">重置</button>','ligand-status','ligand',animated=False,note='沿 z 轴的两个配体被投影为横向示意图，轨道形状为相位示意。中心 s、p_z 与配体能量预设为 −0.6、0.7、0。不同通道分别计算一个 2×2 模型。')
demos['### 4.4']=demo('field-demo','06','同样的 2 + 3 分组，不同的晶场强度','Δ 改变时，哪一组的维数会改变？',slider('field-delta','八面体劈裂 Δ',0,3,.05,1.5)+'<button id="field-reset">重置</button>','field-status','field',note='六个蓝点表示配体，金色表示中心。旋转的是观察视角；在保持理想 O_h 环境的单电子示意中改变 Δ，不引入畸变、交换或电子占据。')
demos['### 4.5']=demo('vibration-demo','07','算出来的水分子振动，而非预录动画','把两侧 H 都换成 D，模式个数、对称性、频率分别怎样变？',slider('vib-kr','伸缩参数 k_r',.4,2,.05,1)+slider('vib-kb','弯曲参数 k_θ',.05,.7,.01,.2)+select('vib-mass','同位素质量',[('1','H₂O · 外侧质量 1'),('2','D₂O · 外侧质量 2')])+slider('vib-amplitude','显示振幅',.03,.22,.01,.12)+'<button id="vib-reset">重置</button>','vibration-status','vibration',extra='<div class="mode-choices" id="mode-choices"><button aria-pressed="true">模式 1</button><button aria-pressed="false">模式 2</button><button aria-pressed="false">模式 3</button></div>',note='平衡键长=1，键角104.5°，m_O=16。弯曲坐标以弧度计算。模型的三个振动由质量加权 Hessian 求得；绝对频率不拟合真实水，内部成分只按本模式最大值重新缩放。')
demos['## 05']=demo('crystal-demo','08','晶体多了什么？平移相位与干涉','N 变大，峰是变高、变窄，还是两者都有？注意图中采用 I/N²。',slider('crystal-n','散射中心数 N',3,40,1,12)+slider('crystal-k','Bloch 相位 k a / π',-1,1,.05,.5)+slider('crystal-q','探测相位 q a / π',0,4,.01,2)+'<button id="crystal-reset">重置</button>','crystal-status','crystal',wide=True,note='上方只画8个原胞的相位箭头，不随 N 改变；下方计算 N 个点的有限链干涉。k 与 q 不是同一个量；归一化使峰值保持1，未归一化峰值为 N²。')
text=(R/'第一章_绪论.md').read_text()
for prefix,content in demos.items():
 m=re.search(r'^'+re.escape(prefix)+r'[^\n]*',text,re.M)
 assert m,prefix
 text=text[:m.start()]+content+'\n\n'+text[m.start():]
protected=[]
def save(t):protected.append(t);return f'ZZSAVE{len(protected)-1}ZZ'
# Protect hand-authored panels before processing Markdown.
text=re.sub(r'<section class="demo\b.*?</section>',lambda m:save(m[0]),text,flags=re.S)
text=re.sub(r'\$\$(.*?)\$\$',lambda m:save('<div class="math-block" tabindex="0" aria-label="公式，可横向滚动">'+convert(m[1].strip(),display='block')+'</div>'),text,flags=re.S)
text=re.sub(r'\$([^$\n]+)\$',lambda m:save(convert(m[1],display='inline')),text)
prose=str(markdown2.markdown(text,extras=['tables','fenced-code-blocks']))
for i,t in enumerate(protected):
 token=f'ZZSAVE{i}ZZ';prose=prose.replace('<p>'+token+'</p>',t).replace(token,t)
prose=re.sub(r'<table>(.*?)</table>',r'<div class="table-scroll"><table>\1</table></div>',prose,flags=re.S)
section=0;toc=[]
def heading(m):
 global section
 section+=1;sid=f'section-{section}';title=re.sub('<[^>]+>','',m[1]);toc.append((sid,title));return '<h2 id="'+sid+'">'+m[1]+'</h2>'
prose=re.sub(r'<h2>(.*?)</h2>',heading,prose,flags=re.S)
